layer.css:
[data-ryt="pitch"] { color: rgb(61, 68, 64); border-left: 1px solid rgb(47, 103, 84); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16.92px; font-weight: 400; font-style: normal; line-height: 1.9; letter-spacing: 0.18px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(61, 68, 64); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 18px; padding-bottom: 0px; padding-left: 18px; transition: all; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { border-top: 1px solid rgba(215, 220, 216, 0.722); border-right: 1px solid rgba(215, 220, 216, 0.722); border-bottom: 1px solid rgba(215, 220, 216, 0.722); border-left: 1px solid rgba(215, 220, 216, 0.722); border-radius: 8px; transition: transform 0.1s }
[data-ryt="footer"] { color: var(--ryt-muted); border-top: 1px solid rgb(215, 221, 216); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: 0.18px; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: 1px; text-underline-offset: 4px; transition: color 0.18s, text-decoration-color 0.18s }
[data-ryt="review"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="cover"] { border-radius: 8px }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 700; font-style: normal; line-height: 3.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="header"] { border-bottom: 1px solid rgb(215, 221, 216); border-top: none }
[data-ryt="nav"] a { color: var(--ryt-muted); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: normal; line-height: 5.143; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: rgb(47, 103, 84); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(47, 103, 84); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.18s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 700; font-style: normal; line-height: 1.35; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-thickness: 1px; text-underline-offset: 5px; transition: text-decoration-color 0.22s }
[data-ryt="rec-card"] [data-ryt="title"]:hover { text-decoration-color: #ad3e32; text-decoration-thickness: 1.5px }
[data-ryt="credit"]:hover, [data-ryt="eyebrow"]:hover { color: #1d2420 }
[data-ryt="credit"] a::after, [data-ryt="review"] a::after, [data-ryt="bio"] a::after { content: ""; display: inline-block; width: 11.1562px; height: 11.1562px; margin-left: 3.96px; color: var(--ryt-accent); background-color: var(--ryt-accent); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.82; letter-spacing: 0.18px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: 4px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-accent) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #ad3e32; text-decoration-color: #ad3e32 }
